from collections import deque,defaultdict
comps=[]; seen=set();
for r in range(g.shape[0]):
 for c in range(g.shape[1]):
  col=int(g[r,c]);
  if col==2 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(x+dx,y+dy)
    if 0<=z[0]<20 and 0<=z[1]<26 and z not in seen and int(g[z])==col:
     seen.add(z);q.append(z)
  comps.append((col,cells))
def norm(cells):
 mnx=min(x for x,y in cells); mny=min(y for x,y in cells)
 return tuple(sorted((x-mnx,y-mny) for x,y in cells))
for i,(col,cells) in enumerate(comps):
 rs=[x for x,y in cells];cs=[y for x,y in cells]
 print(i,col,len(cells),(min(rs),min(cs),max(rs),max(cs)),norm(cells))

def transforms(cells):
 out=[]
 for k in range(4):
  pts=[]
  for x,y in cells:
   # rotate around origin k times
   a,b=x,y
   for _ in range(k): a,b=b,-a
   pts.append((a,b))
  for flip in (1,-1):
   p=[(a,b*flip) for a,b in pts]
   mi=min(a for a,b in p); mj=min(b for a,b in p)
   out.append(tuple(sorted((a-mi,b-mj) for a,b in p)))
 return out
def canon(cells): return min(transforms(cells))
groups=defaultdict(list)
for i,(col,cells) in enumerate(comps):groups[canon(norm(cells))].append((i,col,len(cells), (min(x for x,y in cells),min(y for x,y in cells))))
[(k,v) for k,v in groups.items() if len(v)>1]
